// Writes the legal texts of the site as Markdown files to legal/, for easy review (a lawyer, the owner, the app's
// terms link). The single source stays in src/content (privacy.ts, terms.ts) and src/content/company.ts (company data
// for the imprint); the files in legal/ are generated, do not edit them by hand.
//
//   node scripts/export-legal-markdown.mjs           write legal/*.md
//   node scripts/export-legal-markdown.mjs --check   fail when legal/*.md differ from the sources
//
// Needs Node.js 22.18 or newer (it reads the .ts content files with Node's built in type stripping).
import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { PRIVACY_DE, PRIVACY_EN } from "../src/content/privacy.ts";
import { COMPANY } from "../src/content/company.ts";
import { TERMS_DE, TERMS_EN } from "../src/content/terms.ts";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const out = join(root, "legal");
const check = process.argv.includes("--check");

const NOTE = "<!-- Generated by scripts/export-legal-markdown.mjs from src/content. Do not edit by hand. -->";
const DRAFT =
  "> Entwurf ohne anwaltliche Prüfung (Oktober 2026). / Draft without legal review (October 2026).";

function document(doc, extraTop = []) {
  const lines = [NOTE, "", `# ${doc.title}`, "", `${doc.dateLabel}${doc.note ? ` · ${doc.note}` : ""}`, "", DRAFT, "", ...extraTop];
  for (const section of doc.sections) {
    lines.push(`## ${section.heading}`, "");
    for (const block of section.blocks) {
      if (typeof block === "string") lines.push(block, "");
      else lines.push(...block.list.map((item) => `- ${item}`), "");
    }
  }
  return lines.join("\n").replace(/\n{3,}/g, "\n\n").trimEnd() + "\n";
}

function addressLines(name) {
  return [name, COMPANY.street, `${COMPANY.postalCode} ${COMPANY.city}`];
}

function imprint(lang) {
  const de = lang === "de";
  const directors = COMPANY.managingDirectors.join(", ");
  const rows = de
    ? [
        ["Geltungsbereich", "Dieses Impressum gilt für die Website code-review.com und für die Anwendung unter app.code-review.com."],
        ["Anbieter", [...addressLines(COMPANY.name), COMPANY.countryDe].join("  \n")],
        ["Vertreten durch die Geschäftsführer", directors],
        ["Telefon", COMPANY.phone],
        ["E-Mail", COMPANY.email],
        ["Web", COMPANY.web],
        ["Registereintrag", `Registergericht: ${COMPANY.registerCourt}  \nRegisternummer: ${COMPANY.registerNumber}`],
        ["Umsatzsteuer-Identifikationsnummer gemäß § 27a UStG", COMPANY.vatId],
        [
          "Verantwortlich für den Inhalt nach § 18 Abs. 2 MStV",
          [COMPANY.contentResponsible, `c/o ${COMPANY.name}`, COMPANY.street, `${COMPANY.postalCode} ${COMPANY.city}`].join("  \n"),
        ],
        [
          "Verbraucherstreitbeilegung",
          "Wir sind nicht bereit und nicht verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.",
        ],
      ]
    : [
        ["Scope", "This imprint covers the website code-review.com and the application at app.code-review.com."],
        ["Provider", [...addressLines(COMPANY.name), COMPANY.country].join("  \n")],
        ["Represented by the managing directors", directors],
        ["Phone", COMPANY.phone],
        ["Email", COMPANY.email],
        ["Web", COMPANY.web],
        ["Commercial register", `Register court: ${COMPANY.registerCourt}  \nRegister number: ${COMPANY.registerNumber}`],
        ["VAT ID according to § 27a UStG", COMPANY.vatId],
        [
          "Responsible for the content according to § 18 (2) MStV",
          [COMPANY.contentResponsible, `c/o ${COMPANY.name}`, COMPANY.street, `${COMPANY.postalCode} ${COMPANY.city}`].join("  \n"),
        ],
        [
          "Consumer dispute resolution",
          "We are neither willing nor obliged to take part in dispute resolution proceedings before a consumer arbitration board.",
        ],
      ];
  const lines = [
    NOTE,
    "",
    de ? "# Impressum" : "# Imprint (English translation)",
    "",
    de ? "Angaben gemäß § 5 DDG" : "Information according to § 5 DDG. The German version is the binding one.",
    "",
    DRAFT,
    "",
  ];
  for (const [term, value] of rows) lines.push(`**${term}**  `, value, "");
  return lines.join("\n").trimEnd() + "\n";
}

const files = {
  "impressum.de.md": imprint("de"),
  "imprint.en.md": imprint("en"),
  "datenschutzerklaerung.de.md": document(PRIVACY_DE),
  "privacy-policy.en.md": document(PRIVACY_EN),
  "agb.de.md": document(TERMS_DE),
  "terms-of-service.en.md": document(TERMS_EN),
};

let differs = false;
if (!check) mkdirSync(out, { recursive: true });
for (const [name, content] of Object.entries(files)) {
  const path = join(out, name);
  if (check) {
    if (!existsSync(path) || readFileSync(path, "utf8") !== content) {
      console.error(`legal/${name} is out of date`);
      differs = true;
    }
  } else {
    writeFileSync(path, content);
    console.log(`wrote legal/${name}`);
  }
}
if (check && differs) {
  console.error("Run: node scripts/export-legal-markdown.mjs");
  process.exit(1);
}
